# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Invoices::ReservationOutcome do
  # "state: `prepared`, `committed`, `aborted`, `refused` or `retryable`; conflicts as a list of entry_id and reason; counts"
  it "refuses an unknown state and keeps counts and conflicts when the caller changes them later" do
    expect { described_class.new(state: "pending", conflicts: [], counts: {}) }.to raise_error(ArgumentError)

    conflicts = [{ entry_id: 4, reason: +"on_another_invoice" }]
    counts = { billed: 2 }
    outcome = described_class.new(state: "refused", conflicts:, counts:)

    conflicts.first[:reason] << "_changed"
    conflicts << { entry_id: 5, reason: "not_found" }
    counts[:billed] = 99

    expect(outcome.conflicts).to eq([{ entry_id: 4, reason: "on_another_invoice" }])
    expect(outcome.counts).to eq(billed: 2)
  end
end
